def anti_shuffle(s):
    words = s.split(' ')
    result_words = []
    for w in words:
        if len(w) <= 1:
            result_words.append(w)
            continue
        i = 0
        while i < len(w) and not w[i].isalpha():
            i += 1
        j = len(w) - 1
        while j >= 0 and not w[j].isalpha():
            j -= 1
        if i > j:
            # no alphabets in word
            result_words.append(w)
            continue
        prefix = w[:i]
        suffix = w[j+1:]
        core = w[i:j+1]
        sorted_core = ''.join(sorted(core))
        result_words.append(prefix + sorted_core + suffix)
    return ' '.join(result_words)

